-- Smart Campus Platform — reference schema (PostgreSQL)
-- In the real project EF Core migrations create these tables.
-- Names follow EF Core's Npgsql defaults (PascalCase, quoted) so seed.sql
-- runs unchanged against the migrated database.

DROP TABLE IF EXISTS "Notifications", "Registrations", "Bookings",
                     "Speakers", "Events", "Facilities", "Users" CASCADE;

-- ===== Auth service =====
CREATE TABLE "Users" (
    "Id"            INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name"          VARCHAR(120) NOT NULL,
    "UniversityId"  VARCHAR(20)  NOT NULL UNIQUE,
    "Email"         VARCHAR(160) NOT NULL UNIQUE,
    "PasswordHash"  VARCHAR(100) NOT NULL,
    "Role"          VARCHAR(20)  NOT NULL CHECK ("Role" IN ('Student','Faculty','Admin')),
    "CreatedAt"     TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- ===== Facility Catalog service =====
CREATE TABLE "Facilities" (
    "Id"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title"     VARCHAR(120) NOT NULL,
    "Building"  VARCHAR(80)  NOT NULL,
    "Location"  VARCHAR(120) NOT NULL,
    "Capacity"  INT          NOT NULL CHECK ("Capacity" > 0),
    "Type"      VARCHAR(20)  NOT NULL CHECK ("Type" IN ('Room','Lab','Equipment')),
    "Status"    VARCHAR(20)  NOT NULL CHECK ("Status" IN ('Available','Maintenance'))
);

CREATE TABLE "Events" (
    "Id"          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title"       VARCHAR(160) NOT NULL,
    "Description" TEXT         NOT NULL,
    "Category"    VARCHAR(40)  NOT NULL,
    "Building"    VARCHAR(80)  NOT NULL,
    "Location"    VARCHAR(120) NOT NULL,
    "StartTime"   TIMESTAMPTZ  NOT NULL,
    "EndTime"     TIMESTAMPTZ  NOT NULL,
    "Capacity"    INT          NOT NULL CHECK ("Capacity" > 0),
    "Status"      VARCHAR(20)  NOT NULL CHECK ("Status" IN ('Scheduled','Changed','Cancelled')),
    CHECK ("EndTime" > "StartTime")
);

CREATE TABLE "Speakers" (
    "Id"          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EventId"     INT          NOT NULL REFERENCES "Events"("Id") ON DELETE CASCADE,
    "Name"        VARCHAR(120) NOT NULL,
    "Affiliation" VARCHAR(160) NOT NULL,
    "Bio"         TEXT         NOT NULL
);

-- ===== Booking Engine service =====
-- UserId / FacilityId / EventId point to other services, so no foreign keys here
-- (validated through the owning service's API, SRS 6.3).
CREATE TABLE "Bookings" (
    "Id"          INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId"      INT          NOT NULL,
    "FacilityId"  INT          NOT NULL,
    "StartTime"   TIMESTAMPTZ  NOT NULL,
    "EndTime"     TIMESTAMPTZ  NOT NULL,
    "Status"      VARCHAR(20)  NOT NULL CHECK ("Status" IN ('Confirmed','Cancelled')),
    "CreatedAt"   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CHECK ("EndTime" > "StartTime")
);

CREATE TABLE "Registrations" (
    "Id"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId"    INT          NOT NULL,
    "EventId"   INT          NOT NULL,
    "Status"    VARCHAR(20)  NOT NULL CHECK ("Status" IN ('Registered','Cancelled')),
    "CreatedAt" TIMESTAMPTZ  NOT NULL DEFAULT now()
);
-- one active registration per user per event
CREATE UNIQUE INDEX "UX_Registrations_Active"
    ON "Registrations" ("UserId", "EventId") WHERE "Status" = 'Registered';

-- ===== Notification service =====
CREATE TABLE "Notifications" (
    "Id"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId"    INT          NOT NULL,
    "Type"      VARCHAR(30)  NOT NULL CHECK ("Type" IN ('Confirmation','Reminder','ScheduleChange','Cancellation')),
    "Message"   TEXT         NOT NULL,
    "IsRead"    BOOLEAN      NOT NULL DEFAULT FALSE,
    "CreatedAt" TIMESTAMPTZ  NOT NULL DEFAULT now()
);
